const FALLBACK_SPELL_TYPES: SpellPowerType[] = [
  'Урон',
  'Лечение',
  'Защита',
  'Бафф',
  'Дебафф',
  'Контроль',
];

function comboKey(elements: ElementId[]) {
  return [...new Set(elements)]
    .sort((a, b) => ELEMENT_ORDER.indexOf(a) - ELEMENT_ORDER.indexOf(b))
    .join('|');
}

export function getElementLabel(id: string) {
  return MAGIC_ELEMENTS.find((element) => element.id === id)?.label ?? id;
}

export function getElementColor(id: string) {
  return MAGIC_ELEMENTS.find((element) => element.id === id)?.color ?? '#9ca3af';
}

export function getMagicSuggestions(selected: ElementId[]): MagicSuggestion[] {
  if (!selected.length) return [];

  const normalized = [...new Set(selected)].sort(
    (a, b) => ELEMENT_ORDER.indexOf(a) - ELEMENT_ORDER.indexOf(b),
  );

  const names =
    normalized.length === 1
      ? SINGLE_ELEMENT_INSPIRATIONS[normalized[0]] ?? []
      : MAGIC_SYNTHESIS[comboKey(normalized)] ?? [];

  return names.map((name, index) => ({
    id: `${comboKey(normalized)}-${index + 1}`,
    name,
    elements: normalized,
    description: 'Магия-вдохновитель',
    classBoosts: MAGIC_CLASS_BOOSTS[name],
  }));
}

export function getClassScores(selected: ElementId[], magicInspiration: string) {
  const scores: Record<string, number> = {};

  const addBoosts = (boosts: Record<string, number> | undefined) => {
    for (const [classId, weight] of Object.entries(boosts ?? {})) {
      scores[classId] = (scores[classId] ?? 0) + weight;
    }
  };

  const normalizedElements = [...new Set(selected)].sort(
    (a, b) => ELEMENT_ORDER.indexOf(a) - ELEMENT_ORDER.indexOf(b),
  );

  // 1. Базовый характер каждой выбранной природы.
  for (const element of normalizedElements) {
    addBoosts(ELEMENT_CLASS_WEIGHTS[element]);
  }

  // 2. Синергия конкретной пары элементов.
  // Для троек/четвёрок учитываются все входящие пары.
  for (let i = 0; i < normalizedElements.length; i += 1) {
    for (let j = i + 1; j < normalizedElements.length; j += 1) {
      addBoosts(COMBINATION_CLASS_BOOSTS[comboKey([normalizedElements[i], normalizedElements[j]])]);
    }
  }

  // 3. Чем сложнее синтез, тем полезнее становятся универсальные классы.
  if (normalizedElements.length >= 3) {
    addBoosts({ support_x3: 2, summoner_multi: 1, buffer_debuffer: 1 });
  }
  if (normalizedElements.length >= 4) {
    addBoosts({ support_x3: 2, summoner_multi: 2 });
  }

  const inspiration = magicInspiration.trim();
  const normalizedInspiration = inspiration.toLowerCase();

  // 4. Точечные бонусы известных вдохновителей.
  addBoosts(MAGIC_CLASS_BOOSTS[inspiration]);

  // 5. Смысл названия вдохновителя.
  // Работает для всего большого справочника без ручной разметки 1496 названий.
  if (normalizedInspiration && normalizedInspiration !== 'своя идея') {
    for (const rule of INSPIRATION_KEYWORD_RULES) {
      if (rule.words.some((word) => normalizedInspiration.includes(word))) {
        addBoosts(rule.boosts);
      }
    }
  }

  return scores;
}

export function getSpellTypes(classKey: string | null): SpellPowerType[] {
  if (!classKey) return FALLBACK_SPELL_TYPES;
  return CLASS_SPELL_TYPES[classKey] ?? FALLBACK_SPELL_TYPES;
}